float drawCircle(vec2 uv, vec2 center, float radius) {
    return smoothstep(radius + 0.01, radius - 0.01, length(uv - center));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    float aspect = iResolution.x / iResolution.y;
    uv.x *= aspect;

    vec2 center = vec2(0.0, 0.0);
    float largeRadius = 1.0;

    if (length(uv - center) > largeRadius) {
        discard;
    }

    float angle = radians(360.0 * (mod(iTime * 70.0, 100.0) / 100.0));
    float orbitRadius = 0.4 * largeRadius;
    vec2 smallCenter = center + vec2(cos(angle), sin(angle)) * orbitRadius;
    float smallRadius = 0.5;

    float largeCircle = drawCircle(uv, center, largeRadius);
    float smallCircle = drawCircle(uv, smallCenter, smallRadius);

    float circleMask = largeCircle - smallCircle;

    fragColor = vec4(vec3(circleMask), 1.0);
}
